import prisma from '@/lib/prisma';

// Meta dataset created for the EduExpress website in Events Manager.
// Admin settings and environment variables still take precedence.
export const DEFAULT_META_PIXEL_ID = '4631458287174571';

// The Setting delegate is generated by `prisma generate` at build time. We access
// it through a narrow typed view so this file compiles even before generation.
type SettingRow = { key: string; value: string };
const settingDb = prisma as unknown as {
  setting: {
    findMany: () => Promise<SettingRow[]>;
    upsert: (args: {
      where: { key: string };
      update: { value: string };
      create: { key: string; value: string };
    }) => Promise<SettingRow>;
  };
};

// Keys the admin Settings page manages.
export const SETTING_KEYS = [
  'siteName',
  'siteDescription',
  'contactEmail',
  'contactPhone',
  'whatsappNumber',
  'address',
  'facebookUrl',
  'linkedinUrl',
  'instagramUrl',
  'youtubeUrl',
  'introVideoTitle',
  'introVideoUrl',
  'introVideoPoster',
  'metaPixelId',
  'metaAccessToken',
  'gtmId',
  'ga4Id',
] as const;

export type SettingKey = (typeof SETTING_KEYS)[number];

const MAX_LENGTHS: Record<SettingKey, number> = {
  siteName: 120, siteDescription: 500, contactEmail: 254, contactPhone: 40,
  whatsappNumber: 40, address: 500, facebookUrl: 500, linkedinUrl: 500,
  instagramUrl: 500, youtubeUrl: 500, introVideoTitle: 160, introVideoUrl: 500,
  introVideoPoster: 500, metaPixelId: 32, metaAccessToken: 4096, gtmId: 32, ga4Id: 32,
};

const URL_KEYS = new Set<SettingKey>([
  'facebookUrl', 'linkedinUrl', 'instagramUrl', 'youtubeUrl', 'introVideoUrl',
]);

function isHttpUrl(value: string) {
  try {
    const url = new URL(value);
    return url.protocol === 'https:' || url.protocol === 'http:';
  } catch {
    return false;
  }
}

export function validateSettings(values: unknown): {
  values?: Partial<Record<SettingKey, string>>;
  error?: string;
} {
  if (!values || typeof values !== 'object' || Array.isArray(values)) {
    return { error: 'Settings must be submitted as an object.' };
  }

  const cleanValues: Partial<Record<SettingKey, string>> = {};
  for (const [rawKey, rawValue] of Object.entries(values)) {
    if (!(SETTING_KEYS as readonly string[]).includes(rawKey)) continue;
    const key = rawKey as SettingKey;
    if (typeof rawValue !== 'string') return { error: `${key} must be text.` };
    const value = rawValue.trim();
    if (value.length > MAX_LENGTHS[key]) return { error: `${key} is too long.` };
    if (value && URL_KEYS.has(key) && !isHttpUrl(value)) return { error: `${key} must be a valid http or https URL.` };
    if (key === 'introVideoPoster' && value && !value.startsWith('/') && !isHttpUrl(value)) return { error: 'introVideoPoster must be a site path or valid URL.' };
    if (key === 'contactEmail' && value && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) return { error: 'contactEmail must be a valid email address.' };
    if (key === 'metaPixelId' && value && !/^\d{10,32}$/.test(value)) return { error: 'Meta Pixel ID must contain 10–32 digits.' };
    if (key === 'gtmId' && value && !/^GTM-[A-Z0-9]+$/i.test(value)) return { error: 'Google Tag Manager ID must use the format GTM-XXXXXXX.' };
    if (key === 'ga4Id' && value && !/^G-[A-Z0-9]+$/i.test(value)) return { error: 'GA4 Measurement ID must use the format G-XXXXXXXXXX.' };
    cleanValues[key] = key === 'gtmId' || key === 'ga4Id' ? value.toUpperCase() : value;
  }
  return { values: cleanValues };
}

/** Read all settings as a plain object. Missing keys are simply absent. */
export async function getAllSettings(): Promise<Record<string, string>> {
  try {
    const rows = await settingDb.setting.findMany();
    return Object.fromEntries(rows.map((r) => [r.key, r.value]));
  } catch {
    return {};
  }
}

/** Upsert a batch of settings. Only known keys are written. */
export async function saveSettings(values: Record<string, unknown>): Promise<void> {
  const entries = Object.entries(values).filter(
    ([k, v]) => (SETTING_KEYS as readonly string[]).includes(k) && v !== undefined && v !== null
  );
  await Promise.all(
    entries.map(([key, value]) =>
      settingDb.setting.upsert({
        where: { key },
        update: { value: String(value) },
        create: { key, value: String(value) },
      })
    )
  );
}

/**
 * Meta config: DB value takes precedence, environment variable is the fallback.
 * This lets the admin panel override env without a redeploy.
 */
export async function getMetaConfig(): Promise<{ pixelId: string | null; accessToken: string | null }> {
  const settings = await getAllSettings();
  const pixelId = settings.metaPixelId || process.env.NEXT_PUBLIC_META_PIXEL_ID || DEFAULT_META_PIXEL_ID;
  const accessToken = settings.metaAccessToken || process.env.META_ACCESS_TOKEN || null;
  return { pixelId, accessToken };
}

const clean = (v: string | undefined, ...placeholders: string[]) =>
  v && !placeholders.includes(v) ? v : null;

/**
 * Non-sensitive public tag IDs (Meta Pixel, GTM container, GA4). Safe to expose
 * to the browser. DB values take precedence over environment variables.
 */
export async function getPublicTagConfig(): Promise<{
  metaPixelId: string | null;
  gtmId: string | null;
  ga4Id: string | null;
}> {
  const s = await getAllSettings();
  return {
    metaPixelId: clean(s.metaPixelId || process.env.NEXT_PUBLIC_META_PIXEL_ID, '1234567890') || DEFAULT_META_PIXEL_ID,
    gtmId: clean(s.gtmId || process.env.NEXT_PUBLIC_GTM_ID, 'GTM-XXXXXXX'),
    ga4Id: clean(s.ga4Id || process.env.NEXT_PUBLIC_GA4_MEASUREMENT_ID, 'G-XXXXXXXXXX'),
  };
}
